#include <benchmark/benchmark.h>
#include <vector>

static void BM_SpreadSum(benchmark::State& state) {
    const int n = state.range(0);
    std::vector<double> bid(n, 99.5), ask(n, 100.0);   // set up OUTSIDE the timer
    for (auto _ : state) {                             // state tracks iterations + time
        double s = 0.0;
        for (int i = 0; i < n; ++i) s += ask[i] - bid[i];
        benchmark::DoNotOptimize(s);   // work survives: s must 'exist'
        benchmark::ClobberMemory();    // stores/loads cannot be elided
    }
    state.SetItemsProcessed(state.iterations() * n);
}
BENCHMARK(BM_SpreadSum)->Arg(1 << 10)->Arg(1 << 20);
BENCHMARK_MAIN();

#include <algorithm>
#include <cmath>
#include <vector>

// Nearest-rank percentile on a sorted vector (ascending).
int percentile(const std::vector<int>& sorted, double p) {
    const std::size_t rank =
        static_cast<std::size_t>(std::ceil(p / 100.0 * sorted.size()));
    return sorted[rank - 1];   // ranks are 1-based; indices are 0-based
}
